import Foundation
import HoplaKit
import OmcpFFI

/// Production `OmcpCore`: the Rust omcp-core through the omcp-ffi UniFFI bindings
/// (generated by `scripts/build-rust.sh` into the `OmcpFFI` framework target). Every
/// crypto, backup, burn, file-cap and gateway decision is made in Rust.
public final class RustOmcpCore: HoplaKit.OmcpCore {
    public let linked = true
    public var suiteLabel: String { OmcpFFI.suiteLabel() }
    private var node: OmcpNode?

    public init() {}

    private func n() throws -> OmcpNode {
        guard let node else { throw CoreError.notLoaded }
        return node
    }

    private static func map(_ e: Error) -> Error {
        guard let f = e as? FfiError else { return e }
        switch f {
        case .WrongBackupPassword: return CoreError.wrongBackupPassword
        case .Invalid(let msg): return CoreError.invalid(msg)
        case .FileTooLarge(let size, let max): return CoreError.fileTooLarge(size: size, max: max)
        case .UnknownContact: return CoreError.invalid("unknown contact")
        case .Protocol(let msg), .State(let msg): return CoreError.other(msg)
        case .Storage(let msg): return CoreError.storageUnavailable(msg)
        }
    }

    private func call<T>(_ f: () throws -> T) throws -> T {
        do { return try f() } catch { throw Self.map(error) }
    }

    static func contact(_ c: ContactInfo) -> Contact {
        Contact(id: c.contactId, displayName: c.displayName, safetyNumber: c.safetyNumber, verified: c.verified)
    }

    static func spec(_ s: HoplaKit.BurnSpec) -> OmcpFFI.BurnSpec {
        OmcpFFI.BurnSpec(mode: s.mode == .onOpen ? .onOpen : .timer, secs: UInt32(s.secs), unreadTtl: UInt32(s.unreadTtlSecs))
    }

    static func spec(_ s: OmcpFFI.BurnSpec) -> HoplaKit.BurnSpec {
        HoplaKit.BurnSpec(mode: s.mode == .onOpen ? .onOpen : .timer, secs: Int(s.secs), unreadTtlSecs: Int(s.unreadTtl))
    }

    static func result(_ o: LinkOutput) -> LinkResult {
        LinkResult(
            outgoing: o.outgoing,
            received: o.received.map {
                IncomingText(contactId: $0.contactId, text: $0.text, createdMs: Int64($0.createdMs),
                             envelopeId: $0.envelopeIdHex, burn: $0.burn.map(spec), mime: $0.mime)
            },
            established: o.established, peerContactId: o.peerContactId, flushed: Int(o.flushed),
            opened: o.opened.map {
                OpenedInfo(contactId: $0.contactId, msgId: $0.msgIdHex, openedMs: Int64($0.openedMs),
                           shredded: $0.shredded, burnAtMs: $0.burnAtMs.map(Int64.init))
            },
            fileProgress: o.fileProgress.map {
                FileProgressInfo(transferId: $0.transferIdHex, contactId: $0.contactId, incoming: $0.incoming, name: $0.name,
                                 size: $0.size, doneChunks: Int($0.doneChunks), totalChunks: Int($0.totalChunks))
            },
            files: o.files.map {
                ReceivedFileInfo(transferId: $0.transferIdHex, contactId: $0.contactId, name: $0.name, mime: $0.mime, bytes: $0.bytes)
            },
            fileFailures: o.fileFailures.map { FileFailureInfo(transferId: $0.transferIdHex, contactId: $0.contactId, reason: $0.reason) },
            morePending: o.morePending)
    }

    public func generateRecoveryPhrase() throws -> String { try call { try OmcpFFI.generateRecoveryPhrase() } }
    public func validateRecoveryPhrase(_ phrase: String) -> Bool { OmcpFFI.validateRecoveryPhrase(phrase: phrase) }
    public func suggestRecoveryWords(_ prefix: String) -> [String] { OmcpFFI.suggestRecoveryWords(prefix: prefix) }

    public func load(phrase: String, displayName: String) throws -> Identity {
        let node = try call { try OmcpNode.fromPhrase(phrase: phrase, displayName: displayName) }
        self.node = node
        let i = node.identity()
        return Identity(peerIdHex: i.peerIdHex, displayName: i.displayName)
    }

    @discardableResult
    public func open(phrase: String, displayName: String, dbPath: String, storageKey: Data) throws -> Identity {
        let node = try call {
            try OmcpNode.open(phrase: phrase, displayName: displayName, dbPath: dbPath, storageKey: storageKey)
        }
        self.node = node
        let i = node.identity()
        return Identity(peerIdHex: i.peerIdHex, displayName: i.displayName)
    }

    public func generateStorageKey() throws -> Data { try call { try OmcpFFI.generateStorageKey() } }

    public func storedMessages(_ contactId: String) -> [StoredMessageInfo] {
        ((try? node?.storedMessages(contactId: contactId)) ?? []).map(Self.stored)
    }

    public func setReceivedFilePath(_ transferId: String, path: String?) throws {
        try call { try n().setReceivedFilePath(transferIdHex: transferId, localPath: path) }
    }

    public func restoreHistory(_ history: Data) throws { try call { try n().restoreHistory(history: history) } }

    static func stored(_ m: OmcpFFI.StoredMessage) -> StoredMessageInfo {
        let status: ChatMessage.Status
        switch m.status {
        case .queued: status = .queued
        case .sent: status = .sent
        case .received: status = .received
        }
        let burnState: ChatMessage.BurnState
        switch m.burnState {
        case .none: burnState = .none
        case .unopened: burnState = .unopened
        case .open: burnState = .open
        case .opened: burnState = .opened
        }
        let file = m.file.map { f -> StoredFileInfo in
            let st: FileAttachment.State
            switch f.state {
            case .queued: st = .queued
            case .sending: st = .sending
            case .receiving: st = .receiving
            case .paused: st = .paused
            case .sent: st = .sent
            case .received: st = .received
            case .failed: st = .failed
            case .integrityFailed: st = .integrityFailed
            }
            return StoredFileInfo(name: f.name, mime: f.mime, size: f.size, state: st, doneBytes: f.doneBytes, localPath: f.localPath)
        }
        return StoredMessageInfo(id: m.idHex, contactId: m.contactId, text: m.text, mine: m.mine, timeMs: Int64(m.timeMs),
                                 status: status, mime: m.mime, burn: m.burn.map(spec), burnState: burnState,
                                 burnAtMs: m.burnAtMs.map(Int64.init), file: file)
    }

    public func identity() -> Identity? {
        node.map { let i = $0.identity(); return Identity(peerIdHex: i.peerIdHex, displayName: i.displayName) }
    }

    public func qrPayload() throws -> String { try n().qrPayload() }
    public func advertisement() throws -> Data { try n().advertisement() }

    public func previewContact(_ payload: String) throws -> HoplaKit.ContactPreview {
        let p = try call { try n().previewContactFromQr(payload: payload) }
        return HoplaKit.ContactPreview(contact: Self.contact(p.contact), alreadyKnown: p.alreadyKnown,
                                       mismatchWith: p.mismatchWith.map(Self.contact))
    }

    public func addContactFromQr(_ payload: String) throws -> Contact {
        Self.contact(try call { try n().addContactFromQr(payload: payload) })
    }

    public func restoreContact(_ c: Contact) throws {
        try call { try n().restoreContact(contactId: c.id, displayName: c.displayName, verified: c.verified) }
    }

    public func contacts() -> [Contact] { (node?.contacts() ?? []).map(Self.contact) }
    public func setVerified(_ contactId: String, _ verified: Bool) throws {
        try call { try n().setVerified(contactId: contactId, verified: verified) }
    }

    public func contactForAdvertisement(_ adv: Data) -> String? {
        guard let prefix = OmcpFFI.parseAdvertisement(bytes: adv) else { return nil }
        return node?.contactForPrefix(prefixHex: prefix)
    }

    public func queueMessage(_ contactId: String, text: String, burn: HoplaKit.BurnSpec?) throws -> String {
        try call { try n().queueMessage(contactId: contactId, text: text, burn: burn.map(Self.spec)) }
    }

    public func queueMedia(_ contactId: String, mime: String, bytes: Data, burn: HoplaKit.BurnSpec?) throws -> String {
        try call { try n().queueMedia(contactId: contactId, mime: mime, bytes: bytes, burn: burn.map(Self.spec)) }
    }

    public func openBurn(_ msgId: String, nowMs: Int64) throws -> HoplaKit.BurnContent? {
        try call { try n().openBurn(msgIdHex: msgId, nowMs: UInt64(nowMs)) }.map {
            HoplaKit.BurnContent(text: $0.text, bytes: $0.bytes, mime: $0.mime, burnAtMs: $0.burnAtMs.map(Int64.init))
        }
    }

    public func closeBurn(_ msgId: String) throws { try call { try n().closeBurn(msgIdHex: msgId) } }
    public func tickBurn(nowMs: Int64) -> [String] { node?.tickBurn(nowMs: UInt64(nowMs)) ?? [] }
    public func burnIsLive(_ msgId: String) -> Bool { node?.burnIsLive(msgIdHex: msgId) ?? false }
    public func burnSpecValid(_ spec: HoplaKit.BurnSpec) -> Bool { OmcpFFI.burnSpecValid(spec: Self.spec(spec)) }
    public func queueFile(_ contactId: String, name: String, mime: String, bytes: Data) throws -> FileOfferInfo {
        let o = try call { try n().queueFile(contactId: contactId, name: name, mime: mime, bytes: bytes) }
        return FileOfferInfo(transferId: o.transferIdHex, contactId: o.contactId, name: o.name, mime: o.mime, size: o.size,
                             chunks: Int(o.numChunks))
    }

    @discardableResult public func cancelFile(_ transferId: String) -> Bool { node?.cancelFile(transferIdHex: transferId) ?? false }
    public func queuedFor(_ contactId: String) -> Int { Int(node?.queuedFor(contactId: contactId) ?? 0) }

    public func pathStatus() -> MeshStatus {
        guard let s = node?.pathStatus() else { return MeshStatus(nearbyPeers: 0, queuedCount: 0, aggregatePath: .queued) }
        let k: HoplaKit.PathKind
        switch s.path {
        case .mesh: k = .mesh
        case .gateway: k = .gateway
        case .mixed: k = .mixed
        case .queued: k = .queued
        }
        return MeshStatus(nearbyPeers: Int(s.nearbyPeers), queuedCount: Int(s.queuedCount), aggregatePath: k)
    }

    public func openInitiatorLink(_ contactId: String) throws -> CoreLink {
        RustLink(try call { try n().openInitiatorLink(contactId: contactId) })
    }

    public func openResponderLink() throws -> CoreLink { RustLink(try call { try n().openResponderLink() }) }

    public func checkBackupPassword(_ password: String) -> HoplaKit.PasswordCheck {
        let c = OmcpFFI.checkBackupPassword(password: password)
        return HoplaKit.PasswordCheck(ok: c.ok, score: Int(c.score), tooShort: c.tooShort)
    }

    public func createBackup(password: String, deviceHint: String, nowMs: Int64) throws -> Data {
        try call { try n().createBackup(password: password, deviceHint: deviceHint, createdAtMs: UInt64(nowMs)) }
    }

    public func createBackup(key: Data, deviceHint: String, nowMs: Int64) throws -> Data {
        try call { try n().createBackupWithKey(key: key, deviceHint: deviceHint, createdAtMs: UInt64(nowMs)) }
    }

    public func generateBackupKey() throws -> Data { try call { try OmcpFFI.generateBackupKey() } }

    public func backupInfo(_ blob: Data) -> BackupMeta? {
        (try? OmcpFFI.backupInfo(blob: blob)).map {
            BackupMeta(createdAtMs: Int64($0.createdAtMs), deviceHint: $0.deviceHint, needsPassword: $0.needsPassword)
        }
    }

    private static func restored(_ r: OmcpFFI.RestoredBackup) -> HoplaKit.RestoredBackup {
        HoplaKit.RestoredBackup(phrase: r.phrase, contacts: r.contacts.map {
            Contact(id: $0.contactId, displayName: $0.displayName, safetyNumber: [], verified: $0.verified)
        }, history: r.history)
    }

    public func openBackup(_ blob: Data, password: String) throws -> HoplaKit.RestoredBackup {
        Self.restored(try call { try OmcpFFI.openBackupWithPassword(blob: blob, password: password) })
    }

    public func openBackup(_ blob: Data, key: Data) throws -> HoplaKit.RestoredBackup {
        Self.restored(try call { try OmcpFFI.openBackupWithKey(blob: blob, key: key) })
    }

    public func recoveryPhrase() throws -> String { try call { try n().recoveryPhrase() } }
    public func maxFileBytes() -> UInt64 { OmcpFFI.maxFileBytes() }
    public func gatewayDailyCapBytes() -> UInt64 { OmcpFFI.defaultGatewayDailyCapBytes() }

    public func gatewayDecision(wifiOnly: Bool, network: NetworkType, metered: Bool) -> HoplaKit.GatewayDecision {
        let net: Network
        switch network {
        case .offline: net = .offline
        case .wifi: net = .wifi(metered: metered)
        case .cellular: net = .cellular(metered: metered)
        }
        let d = OmcpFFI.gatewayDecision(wifiOnly: wifiOnly, network: net)
        return HoplaKit.GatewayDecision(bridge: d.bridge, meteredWarning: d.meteredWarning)
    }
}

final class RustLink: CoreLink {
    private let link: MeshLink
    init(_ link: MeshLink) { self.link = link }
    private func wrap(_ f: () throws -> LinkOutput) throws -> LinkResult {
        do { return RustOmcpCore.result(try f()) } catch { throw CoreError.other("\(error)") }
    }
    func start() throws -> LinkResult { try wrap { try link.start() } }
    func onPdu(_ pdu: Data) throws -> LinkResult { try wrap { try link.onPdu(pdu: pdu) } }
    func sendText(_ text: String) throws -> LinkResult { try wrap { try link.sendText(text: text) } }
    func flush() throws -> LinkResult { try wrap { try link.flush() } }
    var isEstablished: Bool { link.isEstablished() }
    func close() { link.shutdown() }
}
